export function getTemplateById(id) {
  if (id === 'custom-visual') {
    try {
      const stored = localStorage.getItem('bridge_custom_template');
      if (stored) {
        return JSON.parse(stored);
      }
    } catch (_) {}
  }
  return RESUME_TEMPLATES.find(t => t.id === id) || RESUME_TEMPLATES[0];
}


